(function() {
  window.CardSpoke.Plugin.register('card-timestamps', {
    manifest: {
      name: 'Card Timestamps',
      version: '1.0.0',
      author: 'CardSpoke Community',
      description: 'Shows human-readable created and updated timestamps on each card',
      layer: 'feature',
      permissions: []
    },
    setup: async function(ctx) {
      ctx.logger.info('Card Timestamps loaded');
      if (window.CardSpoke && window.CardSpoke.Middleware) {
        window.CardSpoke.Middleware.register({
          name: 'card-timestamps-render',
          priority: 10,
          operations: ['card.render'],
          handler: async function(mwCtx, next) {
            await next();
            var card = mwCtx.args[0];
            var element = mwCtx.args[1];
            if (!card || !element) return;
            var existing = element.querySelector('.mod-timestamp');
            if (existing) existing.remove();
            var created = card.createdAt ? new Date(card.createdAt).toLocaleString() : 'unknown';
            var updated = card.updatedAt ? new Date(card.updatedAt).toLocaleString() : 'unknown';
            var el = document.createElement('div');
            el.className = 'mod-timestamp';
            el.textContent = 'Created: ' + created + ' | Updated: ' + updated;
            element.appendChild(el);
          }
        });
      }
    },
    teardown: async function(ctx) {
      if (window.CardSpoke && window.CardSpoke.Middleware) {
        window.CardSpoke.Middleware.unregister('card-timestamps-render');
      }
      var stamps = document.querySelectorAll('.mod-timestamp');
      stamps.forEach(function(s) { s.remove(); });
      ctx.logger.info('Card Timestamps disabled');
    }
  });
})();
